exercises.starter:
struct Guard {
    int *count;
    explicit Guard(int *c) : count(c) {}
};

exercises.tests:
#include <cassert>
struct Guard;

static int normal_exit() {
    int n = 0;
    { Guard g(&n); }
    return n;
}

static int early_return() {
    int n = 0;
    for (int i = 0; i < 1; i++) {
        Guard g(&n);
        break;
    }
    return n;
}

static int throwing() {
    int n = 0;
    try {
        Guard g(&n);
        throw 1;
    } catch (int) {}
    return n;
}

int main() {
    assert(normal_exit() == 1);
    assert(throwing() == 1);
    assert(early_return() == 1);
    return 0;
}

exercises.starter:
struct Marker {
    int id;
    int *log;
    int *n;
    Marker(int i, int *l, int *count) : id(i), log(l), n(count) { log[(*n)++] = id; }
};

exercises.tests:
#include <cassert>
struct Marker;
int main() {
    int log[4] = {0}, n = 0;
    {
        Marker a(1, log, &n);
        Marker b(2, log, &n);
        Marker c(3, log, &n);
    }
    assert(n == 3);
    assert(log[0] == 3);
    assert(log[1] == 2);
    assert(log[2] == 1);
    return 0;
}

exercises.starter:
#include <cstddef>
struct Buf {
    int *data = nullptr;
    size_t n = 0;
    Buf() = default;
    explicit Buf(size_t k) : data(new int[k]()), n(k) {}
    Buf(Buf &&o) noexcept : data(o.data), n(o.n) {}
    Buf(const Buf &) = delete;
    Buf &operator=(const Buf &) = delete;
    ~Buf() { delete[] data; }
};

exercises.tests:
#include <cassert>
#include <cstddef>
#include <utility>
struct Buf;
int main() {
    Buf a(4);
    a.data[0] = 7;
    Buf b(std::move(a));
    assert(b.n == 4);
    assert(b.data != nullptr);
    assert(b.data[0] == 7);
    /* The source must be left owning nothing. */
    assert(a.data == nullptr);
    assert(a.n == 0);
    return 0;
}

exercises.starter:
#include <utility>
struct Counted {
    static int moves;
    static int copies;
    int v = 0;
    Counted() = default;
    explicit Counted(int x) : v(x) {}
    Counted(const Counted &o) : v(o.v) { ++copies; }
    Counted(Counted &&o) noexcept : v(o.v) { o.v = 0; ++moves; }
};
int Counted::moves = 0;
int Counted::copies = 0;

void count_ops(int *moves, int *copies) {
    Counted::moves = 0;
    Counted::copies = 0;
    Counted a(5);
    Counted b(std::move(a));
    (void)b;
    *moves = Counted::moves;
    *copies = Counted::copies;
}

exercises.tests:
#include <cassert>
void count_ops(int *, int *);
int main() {
    int m = -1, c = -1;
    count_ops(&m, &c);
    /* A cast, and a reference bound to its result. Nothing was constructed. */
    assert(m == 0);
    assert(c == 0);
    return 0;
}

exercises.starter:
#include <utility>
struct Tracked {
    static int ctors, moves, copies, dtors;
    int v = 0;
    Tracked() { ++ctors; }
    explicit Tracked(int x) : v(x) { ++ctors; }
    Tracked(const Tracked &o) : v(o.v) { ++copies; }
    Tracked(Tracked &&o) noexcept : v(o.v) { o.v = 0; ++moves; }
    ~Tracked() { ++dtors; }
};
int Tracked::ctors = 0;
int Tracked::moves = 0;
int Tracked::copies = 0;
int Tracked::dtors = 0;

Tracked make_direct() { return Tracked(7); }
Tracked make_named() { Tracked t(9); return std::move(t); }

int direct_moves() {
    Tracked::moves = 0;
    { Tracked a = make_direct(); (void)a; }
    return Tracked::moves;
}
int named_moves() {
    Tracked::moves = 0;
    { Tracked a = make_named(); (void)a; }
    return Tracked::moves;
}

exercises.tests:
#include <cassert>
struct Tracked;
int direct_moves();
int named_moves();
Tracked make_direct();
Tracked make_named();
int main() {
    assert(direct_moves() == 0);
    assert(named_moves() == 0);
    return 0;
}

exercises.starter:
#include <utility>
struct Owner {
    int *p = nullptr;
    Owner() = default;
    explicit Owner(int v) : p(new int(v)) {}
    Owner(const Owner &) = delete;
    Owner &operator=(const Owner &) = delete;
    Owner(Owner &&o) noexcept : p(o.p) { o.p = nullptr; }
    Owner &operator=(Owner &&o) noexcept {
        delete p;
        p = o.p;
        o.p = nullptr;
        return *this;
    }
    ~Owner() { delete p; }
};

int assign_value(int a, int b) {
    Owner x(a), y(b);
    x = std::move(y);
    return x.p ? *x.p : -1;
}
int self_assign_value(int a) {
    Owner x(a);
    x = std::move(x);
    return x.p ? *x.p : -1;
}

exercises.tests:
#include <cassert>
int assign_value(int a, int b);
int self_assign_value(int a);
int main() {
    assert(assign_value(1, 2) == 2);
    /* Moving an object from itself must leave it intact. */
    assert(self_assign_value(5) == 5);
    assert(self_assign_value(0) == 0);
    return 0;
}

exercises.starter:
#include <cstddef>
#include <memory>
void sizes(size_t *raw, size_t *uniq, size_t *shared) {
    *raw = sizeof(int *);
    *uniq = sizeof(int *) * 2;
    *shared = sizeof(int *) * 2;
}

exercises.tests:
#include <cassert>
#include <cstddef>
void sizes(size_t *, size_t *, size_t *);
int main() {
    size_t r, u, s;
    sizes(&r, &u, &s);
    assert(r == 8);
    /* Exclusive ownership costs nothing in space. */
    assert(u == 8);
    /* Shared ownership carries a pointer to the counts. */
    assert(s == 16);
    return 0;
}

exercises.starter:
struct Safe {
    bool fail;
    int *flag;
    Safe(bool f, int *fl) : fail(f), flag(fl) {}
    ~Safe() noexcept(false) {
        if (fail) throw 1;
    }
};

int run(bool fail) {
    int flag = 0;
    { Safe s(fail, &flag); }
    return flag;
}

exercises.tests:
#include <cassert>
struct Safe;
int run(bool fail);
int main() {
    /* A cleanup that succeeds leaves the flag alone. */
    assert(run(false) == 0);
    /* One that fails records it and does not propagate. */
    assert(run(true) == 1);
    return 0;
}
